--- /dev/null
+++ b/apps/worker/test/storage-shared-window-maintained-proof.spec.ts
@@ -0,0 +1,252 @@
+import {applyD1Migrations,env,reset,type D1Migration} from 'cloudflare:test';
+import {expect,it,vi} from 'vitest';
+import {createD1InvocationBudget} from '../src/d1-invocation-budget';
+import {createCanonicalSharedFeaturePreparation} from '../src/storage-analytics-canonical-day';
+import {runStorageAnalyticsPass} from '../src/storage-analytics-runtime';
+import {advanceSharedAnalyticsFeatureDay,readSharedAnalyticsFeatureWindowPlan,
+ type SharedAnalyticsFeatureInput,type SharedAnalyticsFeatureWindowPlan} from '../src/storage-analytics-shared-features';
+import * as summaries from '../src/storage-effective-dependency-summaries';
+import {readEffectiveScopeMutationTokens} from '../src/storage-effective-selective-dependencies';
+import * as selective from '../src/storage-effective-selective-dependencies';
+import {readEffectiveTelemetryOwnerDays,readEffectiveTelemetryOwnerDayPage} from '../src/telemetry-usage-effective-reader';
+import {createSharedAnalyticsFeaturePending,appendSharedAnalyticsFeaturePage,finishSharedAnalyticsFeatureDay} from '../src/analytics-shared-features';
+import {initializeSharedAnalyticsCorpusDatabases,seedSharedAnalyticsCorpus,type SharedAnalyticsCorpusMigrations,
+ type SharedAnalyticsCorpus} from './fixtures/shared-analytics-corpus';
+import {createAnalyticsProfile,profileAnalyticsDatabase,summarizeAnalyticsProfile,type AnalyticsStatementObserver} from './helpers/analytics-profile';
+
+const b=env as Env&SharedAnalyticsCorpusMigrations&{STORAGE_ANALYTICS_DB:D1Database;TEST_DELETION_LEDGER_MIGRATIONS:D1Migration[]};
+const source=()=>b.USAGE_MONITOR_DB,target=()=>b.STORAGE_ANALYTICS_DB;
+const sourceId='synthetic-shared-window-maintained-proof',dayMs=86_400_000;
+type Owner=SharedAnalyticsCorpus['owner'];
+type Cost={phase:string;statements:number;rowsRead:number;rowsWritten:number;wallMs:number;inventory:number;dependencyLinks:number;sourceFences:number;metadataFailures:number};
+function measured(costs:Cost[],phase:string,attached=true){
+ const profile=createAnalyticsProfile(),meter=createD1InvocationBudget(950),started=performance.now();
+ const shapes={inventory:0,dependencyLinks:0,sourceFences:0};
+ const observer:AnalyticsStatementObserver=sample=>{
+  if(sample.sql.includes('SELECT DISTINCT observed_day FROM direct'))shapes.inventory++;
+  if(sample.sql.includes('/* batched occurrence links */')||sample.sql.includes('outside_headers AS'))shapes.dependencyLinks++;
+  if(sample.sql.includes('sequence AS generation')&&sample.sql.includes('storage_effective_selective_runtime'))shapes.sourceFences++;
+ };
+ const rawSource=profileAnalyticsDatabase(source(),'source',profile,()=>phase,observer);
+ const rawTarget=profileAnalyticsDatabase(target(),'target',profile,()=>phase,observer);
+ const db={source:meter.wrap(attached?summaries.withMaintainedEffectiveDependencies(rawSource,rawTarget,sourceId,sourceId):rawSource),
+  target:meter.wrap(rawTarget),ledger:meter.wrap(profileAnalyticsDatabase(b.DELETION_LEDGER,'ledger',profile,()=>phase,observer))};
+ return {db,meter,shapes,snapshot(){const result=summarizeAnalyticsProfile(profile);
+  return {statements:meter.queriesUsed,rowsRead:result.rowsRead,rowsWritten:result.rowsWritten,wallMs:performance.now()-started};
+ },finish(){const result=summarizeAnalyticsProfile(profile);
+  costs.push({phase,statements:meter.queriesUsed,rowsRead:result.rowsRead,rowsWritten:result.rowsWritten,
+   wallMs:performance.now()-started,...shapes,metadataFailures:profile.measurementFailures+(profile.statementObserverFailures??1)});
+  expect(meter.queriesUsed).toBeLessThanOrEqual(950);expect(result.statements).toBe(meter.queriesUsed);
+  expect(profile.measurementFailures).toBe(0);expect(profile.statementObserverFailures).toBe(0);
+ }};
+}
+async function setup(costs:Cost[],dense=401){
+ await reset();await initializeSharedAnalyticsCorpusDatabases(source(),target(),b,sourceId);
+ await applyD1Migrations(b.DELETION_LEDGER,b.TEST_DELETION_LEDGER_MIGRATIONS);
+ const corpus=await seedSharedAnalyticsCorpus({source:source(),target:target(),sourceId,sourceNamespace:sourceId,
+  calendarDays:10,graphDays:2,anchorDay:new Date(Date.now()-dayMs).toISOString().slice(0,10),denseUsageRows:dense,
+  targetAuthority:'ordered-delivery'});
+ // Target authority comes only from the real ordered source outbox/delivery.
+ let delivered=false;
+ for(let n=0;n<64;n++){
+  const run=measured(costs,'ordered_delivery',false);
+  try{const result=await runStorageAnalyticsPass({...run.db,sourceId,sourceNamespace:sourceId,publishCommunity:false,
+   maxSteps:32,maxQueries:run.meter.remainingQueries,deadlineMs:Date.now()+55_000});
+   if(result.state==='idle'&&result.reason==='complete'){delivered=true;break;}
+  }finally{run.finish();}
+ }
+ expect(delivered).toBe(true);
+ expect(await target().prepare('SELECT revision,authority_epoch,state FROM analytics_owner_state WHERE source_id=? AND owner_digest=?')
+  .bind(sourceId,corpus.owner.ownerDigest).first()).toEqual({revision:corpus.owner.ownerRevision,authority_epoch:corpus.owner.authorityEpoch,state:'active'});
+ return corpus;
+}
+async function native(owner:Owner,day:string){
+ let pending=createSharedAnalyticsFeaturePending(day,owner.ownerDigest);
+ for(const stream of ['usage','quota','session'] as const){
+  let after:Parameters<typeof readEffectiveTelemetryOwnerDayPage>[1]['after'];
+  do{const page=await readEffectiveTelemetryOwnerDayPage(source(),{sourceNamespace:sourceId,ownerDigest:owner.ownerDigest,
+   ownerRevision:owner.ownerRevision,authorityEpoch:owner.authorityEpoch,day,stream,limit:200,...(after?{after}:{})});
+   pending=await appendSharedAnalyticsFeaturePage(pending,stream,page.rows,page.next);after=page.next??undefined;
+  }while(after);
+ }
+ return finishSharedAnalyticsFeatureDay(pending);
+}
+async function prepare(costs:Cost[],owner:Owner,day:string,canonical=true){
+ for(let n=0;n<120;n++){
+  const run=measured(costs,canonical?'canonical_preparation':'native_preparation',canonical);
+  const input:SharedAnalyticsFeatureInput={...run.db,sourceId,sourceNamespace:sourceId,owner,day,
+   budget:{remainingQueries:()=>run.meter.remainingQueries,now:Date.now,deadlineMs:Date.now()+55_000}};
+  try{const result=await advanceSharedAnalyticsFeatureDay({...input,...(canonical?{canonicalPreparation:createCanonicalSharedFeaturePreparation(input)}:{})});
+   if(result.state==='complete')return result.value;
+   expect(result.state,JSON.stringify(result)).toBe('deferred');
+  }finally{run.finish();}
+ }
+ throw Error('SYNTHETIC_CANONICAL_PREPARATION_BOUND');
+}
+async function acquire(run:ReturnType<typeof measured>,owner:Owner,day:string,canonical=true,range={fromDay:day,throughDay:day},days=[day]){
+ const input:SharedAnalyticsFeatureInput={...run.db,sourceId,sourceNamespace:sourceId,owner,day,
+  budget:{remainingQueries:()=>run.meter.remainingQueries,now:Date.now,deadlineMs:Date.now()+55_000}};
+ return readSharedAnalyticsFeatureWindowPlan({...input,...range,days,metric:'fits',
+  ...(canonical?{canonicalPreparation:createCanonicalSharedFeaturePreparation(input)}:{})});
+}
+function ready(value:Awaited<ReturnType<typeof acquire>>):SharedAnalyticsFeatureWindowPlan{
+ expect(value.state).toBe('complete');if(value.state!=='complete')throw Error('SYNTHETIC_WINDOW_NOT_READY');return value.plan;
+}
+
+it('reuses a genuinely attached canonical native inventory and vector without unchanged raw reconstruction',async({task})=>{
+ const costs:Cost[]=[];let plan:SharedAnalyticsFeatureWindowPlan|undefined;
+ try{
+  const corpus=await setup(costs),day=corpus.graphDates[0]!;
+  const value=await prepare(costs,corpus.owner,day);expect(value).toEqual(await native(corpus.owner,day));
+  expect(value.scalarUsage.length).toBeGreaterThan(400);
+  const run=measured(costs,'window_and_repeated_operations');
+  try{
+   plan=ready(await acquire(run,corpus.owner,day));
+   const initial={...run.shapes},acquisitionCost=run.snapshot();expect(initial.inventory).toBeGreaterThanOrEqual(2);
+   expect(await plan.loadQuota([day])).toEqual([value.quota]);expect(await plan.loadModelUsage([day])).toEqual([value.modelUsage]);
+   let afterTime=day+'T00:00:00.000Z',afterOccurrence='',complete=false;const rows=[];
+   for(let n=0;n<4&&!complete;n++){
+    const page=await plan.usageReader.readPage({day,afterTime,afterOccurrence});expect(page.state).toBe('ready');
+    if(page.state!=='ready')throw Error('SYNTHETIC_WINDOW_PAGE_REFUSED');rows.push(...page.rows);complete=page.complete;
+    const last=page.rows.at(-1);if(last){afterTime=new Date(last.observedAtMs).toISOString();afterOccurrence=last.occurrenceId;}
+   }
+   expect(complete).toBe(true);expect(rows).toEqual(value.scalarUsage);expect(await plan.seal()).toEqual({state:'current'});
+   const added={inventory:run.shapes.inventory-initial.inventory,dependencyLinks:run.shapes.dependencyLinks-initial.dependencyLinks,
+    sourceFences:run.shapes.sourceFences-initial.sourceFences};
+   const totalCost=run.snapshot(),repeatedCost=Object.fromEntries(Object.keys(acquisitionCost).map(key=>{
+    const field=key as keyof typeof acquisitionCost;return [key,totalCost[field]-acquisitionCost[field]];}));
+   Object.assign(task.meta,{maintainedWindowProof:{initial,added,acquisitionCost,repeatedCost,totalCost,
+    actualCanonicalBinding:true,initialNativeInventory:true}});
+   // Baseline must fail this assertion on unchanged source. Counts are physical
+   // observations, not a spy replacing the native reader or its results.
+   expect(added.inventory).toBe(0);expect(added.dependencyLinks).toBe(0);expect(added.sourceFences).toBeGreaterThan(0);
+   expect(plan.logicalBytes().maximumRetainedBytes).toBeLessThanOrEqual(12*1024*1024);
+  }finally{plan?.close();expect(plan?.logicalBytes()).toMatchObject({compactBytes:0,fullDayBytes:0});run.finish();}
+ }finally{Object.assign(task.meta,{maintainedWindowCosts:costs,scope:'canonical component only; migration/source fixture admission and independent native reference excluded; real ordered delivery and canonical coverage/preparation individually metered and reported; no whole-path or full101 performance claim'});}
+},180_000);
+
+for(const mode of ['no_attachment','no_canonical_producer','missing_source_trigger','missing_target_trigger'] as const)
+ it('keeps exact fresh native fallback for '+mode,async()=>{
+  const costs:Cost[]=[],corpus=await setup(costs,12),day=corpus.graphDates[0]!;
+  const canonical=mode!=='no_canonical_producer',expected=await prepare(costs,corpus.owner,day,canonical);
+  const database=mode==='missing_source_trigger'?source():target();
+  const name=mode==='missing_source_trigger'?'storage_effective_selective_correction_fact_insert':'analytics_effective_dependency_contract_v1';
+  let sql:string|null=null;
+  if(mode.startsWith('missing_')){sql=await database.prepare("SELECT sql FROM sqlite_schema WHERE type='trigger' AND name=?").bind(name).first<string>('sql');
+   expect(sql).toBeTruthy();await database.prepare('DROP TRIGGER '+name).run();}
+  const run=measured(costs,'fallback',mode!=='no_attachment');let plan:SharedAnalyticsFeatureWindowPlan|undefined;
+  try{plan=ready(await acquire(run,corpus.owner,day,canonical));const before=run.shapes.inventory;
+   expect(await plan.loadQuota([day])).toEqual([expected.quota]);expect(await plan.seal()).toEqual({state:'current'});
+   expect(run.shapes.inventory-before).toBeGreaterThanOrEqual(4);
+  }finally{plan?.close();run.finish();if(sql)await database.prepare(sql).run();}
+ },180_000);
+
+for(const capability of ['source_trigger','source_index','source_table','target_trigger'] as const)
+ it('closes the canonical window after actual '+capability+' loss and stays closed after restoration',async()=>{
+  const costs:Cost[]=[],corpus=await setup(costs,12),day=corpus.graphDates[0]!;await prepare(costs,corpus.owner,day);
+  const run=measured(costs,'capability_lifetime');let plan:SharedAnalyticsFeatureWindowPlan|undefined;
+  const database=capability==='target_trigger'?target():source();
+  const type=capability==='source_index'?'index':capability==='source_table'?'table':'trigger';
+  const name=capability==='source_index'?'storage_effective_selective_work_owner':capability==='source_table'?'storage_effective_selective_ranges'
+   :capability==='target_trigger'?'analytics_effective_dependency_contract_v1':'storage_effective_selective_correction_fact_insert';
+  let restoration:string|undefined;
+  try{plan=ready(await acquire(run,corpus.owner,day));
+   const sql=await database.prepare('SELECT sql FROM sqlite_schema WHERE type=? AND name=?').bind(type,name).first<string>('sql');expect(sql).toBeTruthy();
+   if(type==='table'){await database.prepare('ALTER TABLE '+name+' RENAME TO synthetic_hidden_ranges').run();restoration='ALTER TABLE synthetic_hidden_ranges RENAME TO '+name;}
+   else{await database.prepare('DROP '+type+' '+name).run();restoration=sql!;}
+   expect((await plan.seal()).state).toBe('deferred');expect(plan.logicalBytes()).toMatchObject({compactBytes:0,fullDayBytes:0});
+   await database.prepare(restoration).run();restoration=undefined;
+   expect((await plan.seal()).state).toBe('deferred');
+  }finally{if(restoration)await database.prepare(restoration).run();plan?.close();run.finish();}
+ },180_000);
+
+it('covers the exact whole interval plus101 singleton scopes and rejects unseeded or foreign admission',async()=>{
+ const costs:Cost[]=[],corpus=await setup(costs,12),day=corpus.graphDates[0]!;
+ type Factory=(source:D1Database,target:D1Database,owner:Owner,sourceId:string,namespace:string,
+  scopes:readonly {fromDay:string;throughDay:string;includeSessions:boolean}[],deadline:number)=>Promise<{current():Promise<boolean>;close():void}|undefined>;
+ const factory=Reflect.get(summaries,'createMaintainedEffectiveHistoryInvocationProof') as Factory;
+ expect(typeof factory).toBe('function');
+ const days=Array.from({length:101},(_,n)=>new Date(Date.parse(day+'T00:00:00.000Z')-(100-n)*dayMs).toISOString().slice(0,10));
+ const scopes=[{fromDay:days[0]!,throughDay:day,includeSessions:true},...days.map(value=>({fromDay:value,throughDay:value,includeSessions:true}))];
+ expect(scopes).toHaveLength(102);
+ const run=measured(costs,'scope_admission');
+ try{
+  expect(await factory(run.db.source,run.db.target,corpus.owner,sourceId,sourceId,scopes,Date.now()+55_000)).toBeUndefined();
+ }finally{run.finish();}
+ await prepare(costs,corpus.owner,day);
+ const covered=measured(costs,'scope_coverage');
+ try{
+  const tokens=await readEffectiveScopeMutationTokens(covered.db.source,{sourceId,sourceNamespace:sourceId,
+   participantId:corpus.owner.participantId,ownerDigest:corpus.owner.ownerDigest},scopes);expect(tokens).toHaveLength(102);
+  for(const [targetId,namespace] of [['synthetic-other',sourceId],[sourceId,'synthetic-other']] as const)
+   expect(await factory(covered.db.source,covered.db.target,corpus.owner,targetId,namespace,scopes,Date.now()+55_000)).toBeUndefined();
+  expect(await factory(covered.db.source,source(),corpus.owner,sourceId,sourceId,scopes,Date.now()+55_000)).toBeUndefined();
+  expect(await factory(covered.db.source,covered.db.target,corpus.owner,sourceId,sourceId,scopes,Date.now()+180_000)).toBeUndefined();
+  const proof=await factory(covered.db.source,covered.db.target,corpus.owner,sourceId,sourceId,scopes,Date.now()+55_000);
+  expect(proof).toBeDefined();expect(await proof!.current()).toBe(true);proof!.close();expect(await proof!.current()).toBe(false);
+ }finally{covered.finish();}
+},180_000);
+
+for(const change of ['new_empty_day','correction','clock_expiry'] as const)
+ it('rejects '+change+' after a positive canonical acquisition',async()=>{
+  const costs:Cost[]=[],corpus=await setup(costs,12),day=corpus.graphDates[0]!;
+  const fromDay=corpus.historyDates[0]!,throughDay=corpus.historyDates.at(-1)!;
+  const inventory={sourceNamespace:sourceId,ownerDigest:corpus.owner.ownerDigest,ownerRevision:corpus.owner.ownerRevision,
+   authorityEpoch:corpus.owner.authorityEpoch,fromDay,throughDay};
+  const quota=await readEffectiveTelemetryOwnerDays(source(),{...inventory,stream:'quota'}),usage=await readEffectiveTelemetryOwnerDays(source(),{...inventory,stream:'usage'});
+  const days=[...new Set([...quota,...usage])].sort();
+  for(const selected of days)await prepare(costs,corpus.owner,selected);
+  const run=measured(costs,'source_lifetime');let plan:SharedAnalyticsFeatureWindowPlan|undefined,clock:ReturnType<typeof vi.spyOn>|undefined;
+  try{plan=ready(await acquire(run,corpus.owner,day,true,{fromDay,throughDay},days));
+   if(change==='new_empty_day'){
+    const empty=corpus.functionalInputs.emptyDay!;expect(empty>=fromDay&&empty<=throughDay&&!days.includes(empty)).toBe(true);
+    const next=await corpus.appendV11Day(empty);expect(next.ownerRevision).toBeGreaterThan(corpus.owner.ownerRevision);
+   }else if(change==='correction'){const next=await corpus.mutateCorrection();expect(next.ownerRevision).toBeGreaterThan(corpus.owner.ownerRevision);}
+   else clock=vi.spyOn(Date,'now').mockReturnValue(Date.now()+120_001);
+   expect((await plan.seal()).state).toBe('deferred');expect(plan.logicalBytes()).toMatchObject({compactBytes:0,fullDayBytes:0});
+   clock?.mockRestore();clock=undefined;expect((await plan.seal()).state).toBe('deferred');
+  }finally{clock?.mockRestore();plan?.close();run.finish();}
+ },180_000);
+
+it('rejects committed native proof loss after retention guards are restored while owner revision stays unchanged',async()=>{
+ const costs:Cost[]=[],corpus=await setup(costs,12),day=corpus.graphDates[0]!;await prepare(costs,corpus.owner,day);
+ const run=measured(costs,'native_proof_loss');let plan:SharedAnalyticsFeatureWindowPlan|undefined;
+ const guards:string[]=[];
+ try{plan=ready(await acquire(run,corpus.owner,day));
+  const proof=await source().prepare(`SELECT p.typed_record_id FROM typed_v11_record_proofs p
+   JOIN typed_v11_manifest_memberships m ON m.typed_manifest_id=p.manifest_key
+   JOIN telemetry_v11_day_manifests d ON d.id=m.manifest_id WHERE d.participant_id=? LIMIT 1`)
+   .bind(corpus.owner.participantId).first<{typed_record_id:number}>();expect(proof).not.toBeNull();
+  const revision=()=>source().prepare('SELECT revision,authority_epoch FROM storage_owner_revisions WHERE owner_digest=?')
+   .bind(corpus.owner.ownerDigest).first();
+  const before=await revision();
+  // Deliberate local corruption control. Admission is genuine; dropping both
+  // retention guards permits the otherwise forbidden physical proof loss.
+  // The existing native/selective deletion invalidators remain installed.
+  for(const name of ['typed_v11_active_proof_delete_guard','typed_v11_retained_proof_delete_guard']){
+   const sql=await source().prepare("SELECT sql FROM sqlite_schema WHERE type='trigger' AND name=?").bind(name).first<string>('sql');
+   expect(sql).toBeTruthy();await source().prepare('DROP TRIGGER '+name).run();guards.push(sql!);
+  }
+  await source().prepare('DELETE FROM typed_v11_record_proofs WHERE typed_record_id=?').bind(proof!.typed_record_id).run();
+  expect(await source().prepare('SELECT count(*) n FROM typed_v11_record_proofs WHERE typed_record_id=?').bind(proof!.typed_record_id).first<number>('n')).toBe(0);
+  for(const sql of guards)await source().prepare(sql).run();guards.length=0;
+  expect(await revision()).toEqual(before);
+  expect((await plan.seal()).state).toBe('deferred');expect(plan.logicalBytes()).toMatchObject({compactBytes:0,fullDayBytes:0});
+ }finally{for(const sql of guards)await source().prepare(sql).run();plan?.close();run.finish();}
+},180_000);
+
+it('rechecks the full source fence after a genuine mutation between the initial fence and target work',async()=>{
+ const costs:Cost[]=[],corpus=await setup(costs,12),day=corpus.graphDates[0]!;await prepare(costs,corpus.owner,day);
+ const run=measured(costs,'endpoint_source_race');let plan:SharedAnalyticsFeatureWindowPlan|undefined;
+ const original=selective.effectiveDependencyReadContextCurrent;let armed=false,changed=false;
+ const check=vi.spyOn(selective,'effectiveDependencyReadContextCurrent').mockImplementation(async(...args)=>{
+  const result=await original(...args);
+  if(armed&&!changed&&result){changed=true;const next=await corpus.appendOutsideV11();
+   expect(next.ownerRevision).toBeGreaterThan(corpus.owner.ownerRevision);}
+  return result;
+ });
+ try{plan=ready(await acquire(run,corpus.owner,day));armed=true;
+  expect((await plan.seal()).state).toBe('deferred');expect(changed).toBe(true);
+  expect(plan.logicalBytes()).toMatchObject({compactBytes:0,fullDayBytes:0});
+ }finally{check.mockRestore();plan?.close();run.finish();}
+},180_000);
